/* Private original expedition staging. Published room keys remain authoritative.
   Loading this preparation records no visit, reward, death, promise or discovery. */
(() => {
  'use strict';
  const ref = (page, note) => ({book:'madMage',page,note});
  const custom = 'Original Echo Below preparation based on the approved campaign outline. Contracts, instrument and dialogue are custom; all outcomes await play and DM approval.';
  const sharedLimits = [
    'Latest confirmed play left Gundren at an inn and the party at Barthen’s Provisions after Glasstaff escaped. These are future Waterdeep expeditions, not completed sessions or evidence of any further Phandelver outcome.',
    'Dungeon Level is written for four level-5 characters (DotMM p.13). Review the actual five-person party and resources before departure. No level, rest, equipment or spell is granted by opening a package.',
    'Use the source-checked Level 1 atlas package. Prepare one persistent floor and stage section views with its saved fog; the old um1-table canvas remains available. Source squares are 10 feet, subdivided to 5 feet for the authored tactical view. Never show the keyed DM drawing to players.',
    'Return to the same tracked saved dungeon. Use the reviewed expedition return to bring current character resources back; do not create fresh occupants, loot, fog or traps for the next contract.',
    'Creature entries below link to full local Monster Manual statistics. Spawn only present creatures at the encounter actually reached, honor saved casualties and relocations, and open the full stat block before combat.',
    'Room 22, cleared rooms and negotiated refuges require a current watch and threat assessment. No rest is guaranteed; a short rest never restores living dungeon enemies by default.',
    'The well is the prepared exit. Room 4 vents admit only Tiny or gaseous creatures; room 24a has a destroyed gate; the room 26d gate requires level 11+ and leads to level 10. None is a shortcut to town or the next contract.',
    'Halaster’s family, Looking Glass design, Aldric’s return and the Nine remain unrevealed. A resonance comparison or courteous note proves only the observed detail. Never identify Trista’s private BELOW token for an NPC who has not learned about it.'
  ];
  const sources = [ref(13,'Level 1 readiness, Undertakers and Xanathar Guild intentions.'),ref(15,'Supplied keyed Dungeon Level map; physical connectivity and 10-foot squares.'),{book:'custom',label:'Echo-Below-Campaign-Outline.md',note:'Act I: the first three expeditions. Original hooks and offers are future preparation.'}];
  const creatures = {
    scouts:[{name:'Bugbear',count:2,book:'mm',page:33,note:'Area 2b only if still present; both have intellect devourers inside. Withdraw south to warn area 23. Do not duplicate there.'},{name:'Intellect Devourer',count:2,book:'mm',page:191,note:'Inside the area-2b hosts; Detect Sentience and host-death behavior are essential. Not two extra bodies on the map at start.'}],
    undertakers:[{name:'Bandit Captain',count:1,book:'mm',page:344,note:'Uktarl in area 6; Performance +4.'},{name:'Bandit',count:6,book:'mm',page:343,note:'Area 6 total; add the entry lookout only if it reached this post.'},{name:'Doppelganger',count:2,book:'mm',page:82,note:'Area 6 total. Not every disguised human is a bandit.'}],
    guild:[{name:'Bugbear',count:2,book:'mm',page:33,note:'Area 23 native guards; add only actual surviving arrivals from area 2b.'},{name:'Intellect Devourer',count:2,book:'mm',page:191,note:'In the native area-23 hosts; add only those arriving in surviving area-2b hosts.'},{name:'Goblin',count:15,book:'mm',page:166,note:'Six in 23a and nine resting in 23c unless moved by recorded events; do not stage all as one unavoidable combat.'}]
  };
  const packages = [
    {
      id:'map',title:'A Map Worth Paying For',questId:'route',summary:'A paid, bounded survey from the entrywell to the northern junction. One contact or obstacle, an honest turnaround, and a useful first return.',
      prerequisites:['The party has chosen Waterdeep and has an actual reason to accept work; Dracuseth stays in the city.','Review level-5 readiness and the local creature cards; no current character level is changed.','Select the existing saved Level 1 expedition, or create it once; reconcile any existing room outcomes and routes before staging.','Agree scope, payment, return contact, daylight-independent turnback time and what the players allow Ilvara to copy.'],
      contract:{scope:'Ilvara Reed wants a sketch of entrywell 1, relief hall 2a, the pillar junction 2b and the northern approach toward 6a. Mark dimensions, visible junctions, who was encountered, time observed and the last point actually reached. The limit is the threshold of occupied area 6, not defeating its inhabitants.',payment:'Suggested custom offer: 60 gp for the group; 10 gp of that advanced toward five round trips at the Portal and 50 gp on accepted delivery. Agree changes before leaving. Advance is not a second reward and is not entered into inventory automatically.',delivery:'Deliver a dated sketch, observations separated from claims, a demonstrated route back and one uncertainty requiring a later visit. Ilvara may retain an agreed copy; sensitive personal details can be redacted.',partial:'Full agreed fee for a credible survey to an encountered stopping point with its hazard or refusal honestly described. A failed attempt can meet the scope. If the party never descends, renegotiate or refund unused advance; do not invent a debt or complete the quest automatically.'},
      route:{rooms:['um1-1','um1-2','um1-6'],description:'Portal well → 1 → ordinary south exit bending west → 2a → steps down into 2b → northern stairs/corridor → eastern branch toward 6a. The northern one-way secret door in area 1 is not an ordinary usable entrance from the well side. Check the actual map for bends and door positions.',alternatives:['End the survey at 2b if scouts, injuries or uncertainty justify it; recording a dangerous southern continuation is a useful deliverable.','If invited by the current Undertakers, measure only the corridor/threshold covered by their permission. Permission for 6a does not include 6c possessions or 7/8.','Optional 4: investigate the dretch relief in 2a or approach from the north corridor only if chosen; it is not a compulsory route or a safe sword reward.','Optional northern west branch leads to 5 and two grells; no contract requires entering it. Retreat along the measured corridor if they pursue.','Avoid using 21 as a western shortcut: its mirror hazard is real. Room 22 can be inspected only via an actually traversed route, not selected remotely as a refuge.'],retreat:'Reverse the physically traveled corridor to 2b → 2a → 1, watching actual scouts/pursuers. Record which point can still be reached, reserve the return fee and keep the ascent order. If cut off, stop at the current point and choose a known passage; do not teleport to the well.'},
      beats:[
        {id:'arc-map-offer',title:'Ilvara draws a small box',scene:'wd-portal',read:['Ilvara places a clean sheet beside your cups and draws a small rectangle. “This is the part I am paying for. Mark where you went, where you stopped, and what made you stop. A warning that brings someone home is a useful map.”'],run:['Offer the proposed contract and let Ringgo or any player amend it. Agree the scope aloud; write the amount and return contact before departure.','Ilvara wants a practical copy for later teams. She does not ask for private character history, confiscation of discoveries, or a clear floor.','Durnan’s published fee is 1 gp per person down and another 1 gp sent up in advance for return. The winch carries one adventurer at a time. Review his exact procedure and arrange a signal; do not charge twice if already paid.','Ask each player to choose one job if desired: route notes, rear watch, measuring, negotiation or supplies. Anyone may swap or decline.'],private:['The later contracts remain optional. Ilvara knows only approved disclosures. A prospective job is not a promise until accepted.'],ask:['What is your turnaround signal?','Who receives your copy, and is anything excluded?','Who should Durnan contact if you are late?'],sources:[ref(6,'Yawning Portal description and entry/return procedure; confirm local printed-page link.'),ref(7,'Portal hooks and climbing guidance.'),...sources]},
        {id:'arc-map-well',title:'Entrywell: leave a route home',scene:'um1-table',read:['Your boots settle into a thin bed of sand. Battered shields hang around the stone chamber. The passage ahead turns out of sight; above you, the tavern is already a distant circle of noise.'],run:['Stage area 1 only, with the well and ordinary south exit. Let the party establish light, order and a non-destructive route mark.','If still alive and stationed here, the bandit beyond the north one-way door listens and goes to warn 6, 8 and 9. DC 20 Wisdom (Perception) hears retreating footsteps; success does not automatically open the door. Record its actual destination, once.','Searching the sand finds the mundane castoffs and a PHB trinket; use the keyed reference, not a new magic clue. Disturbed shields crumble. If the concealed Elvish message is found, it is an old hint about gates, not a reliable escape route.','At a threat or injury, offer the concrete choice to return before moving farther. No wandering encounter is required merely because the rope was used.'],private:['Do not reveal every numbered room or the listening bandit’s hidden identity on the TV. The entry scout is not an additional random encounter.'],ask:['What does your first mark mean?','Who checks the passage while the last person arrives?'],creatures:[{name:'Bandit',count:1,book:'mm',page:343,note:'Behind the one-way door; normally withdraws.'}],sources:[ref(14,'Area 1; lookout, one-way door and mundane finds.'),ref(15,'Entrywell route on map.')]},
        {id:'arc-map-junction',title:'Pillar junction: decide what to follow',scene:'um1-table',read:['Demon reliefs line the broad passage. Shallow steps descend to a forest of pillars, where the light breaks into separate pools. Scratched words point toward the southern exit: “Certain death this way.”'],run:['Stage 2a and the portion of 2b visible from the entrance. Measure the 10-foot descent at the stairs and record the north, west and south approaches as unverified until explored.','Two published bugbear scouts, each containing an intellect devourer, detect approaching minds and withdraw down the southern route toward 23. Their Detect Sentience prevents surprise; Trista’s darkness is useful against sight, not this sense. Compare each Stealth check with passive Perception to see whether the PCs notice them.','Let the party pursue, call out, hold the junction, take the northern route or turn back. Do not convert reconnaissance into a compulsory fight. If chased, use 2b → 25a → 25b west door → unkeyed western passage → 24b south door → 24a north exit → the southern area-23 corridor → 23a/23b. Area 23c is a side room off that corridor, not a through-route. The scouts avoid the western mirrors.','If combat occurs, use both host and intellect-devourer stat blocks. At host 0 HP the devourer emerges to seek a new host. Record survivors and relocation before later staging 23.','The skeletal snake on the northern pillar is harmless but noisy when disturbed; the loose-stone cache in the southern pillar is already empty.'],private:['The scout warning gives the Guild information about actual observed intruders, not their private quests. The marked warning is not proof that the north is safe.'],ask:['Is this enough to make the survey useful, or do you take the northern stairs?','Do you follow the moving figures or preserve your route home?'],creatures:creatures.scouts,sources:[ref(14,'Area 2 approach and reliefs.'),ref(16,'Area 2b scouts and northern/western/southern stairs.'),ref(15,'Physical route, including scout detour.'),ref(21,'Area 23 receives surviving scouts.')]},
        {id:'arc-map-threshold',title:'The Undertakers’ price',scene:'um1-table',read:['Three stone nobles overlook a hall strewn with old bones. Someone steps into the lamplight in elaborate dark clothes. “Visitors,” the figure says, with a smile held a little too long. “Ten gold each, and you may continue.”'],run:['Use this arrival only if Undertakers still control 6. If cleared or abandoned, describe only recorded present features and choose a current contact or an honest empty-route report.','Uktarl’s local force is one bandit captain, six bandits and two doppelgangers, plus the entry lookout only if it arrived. Alerted inhabitants gather in 6a; otherwise preserve keyed locations. Their vampire presentation is a ruse: DC 14 Wisdom (Insight) notices it. This does not make them harmless.','Offer genuine player options: pay the quoted 10 gp each, bargain for only a short survey without entering private rooms, exchange an accurate warning they actually possess, refuse and back away, or fight if chosen. Proposed custom counteroffer: 10 gp for one group visit to the threshold with no private-room search; Uktarl can reject it. A roll cannot bind Harria or the Guild.','Uktarl’s interests are money, apparent authority and outlasting Harria. He may try to point adventurers at the goblinoids. Distinguish any claim about safety from what he actually controls. Agree scope and receipt/sign before payment.','If hurt or seeing an underling slaughtered, Uktarl retreats to 7; others may retreat toward 8. Follow actual pursuit, not a full reinforcement wave from rooms the party has not alerted. The 6b plate alarm and repaired staff can alert adjacent rooms; noise has a location and witnesses.'],private:['Persuasion uncertainty is custom adjudication, not a printed automatic toll-reduction DC. Give the offer and stakes before asking for a check. Do not reveal doppelganger identities through a costume check.'],ask:['Are you asking to cross, to measure, or simply to turn around?','What are you willing to promise, and for how long?'],creatures:creatures.undertakers,sources:[ref(13,'Undertaker disguises, toll and leaders’ rivalry.'),ref(17,'Area 6 composition, alarm and retreat.'),ref(18,'Harria and reinforcements remain in their keyed rooms.')]},
        {id:'arc-map-detours',title:'If they investigate a side branch',scene:'um1-table',read:['Your route can end here with a blank edge, or you can spend more of your light learning what lies beyond it.'],run:['Use only the branch chosen. Area 4: the sword sheds dim light 10 feet, but taking it curses the holder so it returns when pried away. Describe the skeletal hand and blood first. Remove curse or similar magic ends the curse; do not grant an automatic identification or force a hand injury. Voices through the vents are unintelligible.','Area 5: two grells use north/east alcoves for cover; contest Perception against their Stealth. They pursue fleeing prey. Show the corridor back and keep the survey objective available; room contains no treasure.','Area 3 behind the nalfeshnee relief: foul water deepens westward to 6 feet; a psychic gray ooze lurks underwater north of the statue. Use its Psychic Crush variant. The violet statue light is harmless, not Echo evidence.','Do not quietly open an expanded-dungeon tunnel as a new adventure. Mark it unexplored and prepare later. These branches add risks, not required contract boxes.'],private:['These are alternative reference beats. Visiting all three is not the intended first outing. No return card presumes a curse, combat or treasure.'],ask:['Do you want to add this to today’s scope, or mark it for later?'],creatures:[{name:'Grell',count:2,book:'mm',page:172,note:'Area 5 only.'},{name:'Psychic Gray Ooze',count:1,book:'mm',page:243,note:'Area 3 only; use the variant action.'}],sources:[ref(16,'Areas 3, 4 and 5; exact hazards remain keyed.')]},
        {id:'arc-map-withdraw',title:'Close the first survey',scene:'um1-table',read:['The marks you made on the way in now point toward home. Behind you lie measured passages, unanswered questions, and at least one reason to come back better prepared.'],run:['This narration applies when the party chooses to withdraw; if cut off, replace it with the visible problem. Retrace only the mapped path to 1 and resolve real pursuers.','Record exact turnaround position, open/closed doors, warned factions, each living relocated creature, spent supplies and who carries any finds. HP 0 alone does not establish a witness’s final fate.','Offer a comparison with Wave Echo only if a player observed a relevant sensation there and actively compares it now. A mundane sound measurement or “no matching signal” is useful; do not invent a compulsory token pulse.','Use Expedition record → Retreat to preserve the position; then stage the Portal return and city-return beat. Keep upward fee/sequence, injuries and promises in the review.'],private:['The saved dungeon retains successes. A safe trip out does not mark the whole floor cleared or automatically complete a contract.'],ask:['Where did observation become guesswork on your map?','What must the next expedition know before taking this route?'],sources:[ref(6,'Portal return procedure.'),ref(15,'Reverse actual map path.'),ref(26,'Aftermath must follow concrete faction changes.')]}
      ],
      responses:[
        {trigger:'Entry lookout reached the Undertakers',evidence:'A recorded surviving lookout, traveled path and time to deliver a warning.',proposal:'Gather the remaining area-6 force in 6a and let the contacted leaders know only what the lookout observed.',preserves:'No new bandits, restored dead scouts or automatic knowledge of secrets.'},
        {trigger:'Area-2b scouts escaped to 23',evidence:'The two hosts’ actual survival and the traveled southern detour.',proposal:'Move those same scouts to Worg’s Eye; mark that post alerted before its next encounter.',preserves:'Area 2b can remain empty. The two scouts are counted once.'},
        {trigger:'A bounded Undertaker agreement was accepted',evidence:'Named speaker, paid or promised consideration, covered corridor, expiration and any witnessed breach.',proposal:'Honor the stated limit until a recorded breach, leadership change or inability to enforce it needs review.',preserves:'No universal protection from the Guild, grells or rival bandits; no betrayal simply to erase negotiated progress.'},
        {trigger:'Party withdraws without a fight',evidence:'Accurate route notes and observed threat/turnaround reason.',proposal:'Ilvara accepts an honest bounded survey under the agreed contract and offers a later extension, if wanted.',preserves:'Reward follows accepted delivery; monsters remain where actual play left them.'}
      ],
      spotlights:{'pc-pebble':'Primary invitation: choose marks that a nervous traveler could follow, then check them on retreat. His confidence grows from useful work; no compulsory getting-lost episode.','pc-ringgo':'Primary invitation: negotiate a real contract and a bounded passage without blackmail or compulsory violence. Record whose trust he actually earns.','pc-trista':'Offer scouting/rear-watch choices with current Shadow abilities; state limits of Detect Sentience without negating her other tools. She chooses any disclosure.','pc-donavan':'Keep dimensions and distinguish measured fact from a guide’s claim; compare only records the party actually owns.','pc-aldric':'Set a humane turnback rule and protect someone’s chance to withdraw. He can read a relevant language if known; no ring activation or forced memory.'},
      rewards:['Agreed contract payment after review, counting any advance once.','The actually measured route and permission to circulate a redacted copy.','Specific professional credit from Ilvara and any reciprocal contact the party chose; no automatic faction membership.','Only individually recovered keyed treasure, with custody recorded; surveying a room grants none.'],
      returns:['Resolve the 50 gp balance only after accepted delivery under the suggested offer, or the amended terms actually agreed.','Offer the ordinary kept-delivery / lodging-improvement return. An improvement costs chosen time/materials; the party may simply rest.','Stage The Missing Instrument only if they want another bounded job. Existing court relationships and late messages follow recorded events.'],limits:sharedLimits,sources
    },
    {
      id:'instrument',title:'The Missing Instrument',questId:'instrument',summary:'Recover a named surveying tool from the excavation approach, or establish its fate. Salvage rights and credit matter as much as ownership.',
      prerequisites:['Use the same saved Level 1 state and an earned entry route; the first survey can end early without blocking this job.','Choose and record one instrument placement/custodian in prep before departure. Do not seed an already-searched empty room retroactively.','Give Orren a verifiable purchase drawing/serial description and a limited claim; no maker’s missing colleague or death is established yet.','Stage the Gilded Compass only where their independent route and timing permit. If they already retrieved the object, negotiate in the city instead of staging a second object.'],
      contract:{scope:'Orren Brassmantle of Ninepin Works wants his brass survey clinometer, N9-14, or a corroborated account of its current holder and condition. Custom instrument: hinged sighting arm, plumb bob, replaceable glass vial, scratched offset mark under the foot; a mundane tool, not a magic detector.',payment:'Suggested custom offer: 80 gp for verified return with custody settled, or 20 gp for a corroborated location/fate report. Agree whether the 20 gp is credited against later recovery; default yes, so at most 80 gp total. No advance or automatic treasure award.',delivery:'Compare the serial, sketch and repair mark; list damage without destroying it. Record which claimant releases it and any purchased salvage share. Orren can accept repairable damage under the agreed terms.',partial:'A named holder, witnessed refusal, accurate sketch or credible broken remains can earn the agreed report fee. A rumor alone remains a lead. If no descent is safe, try a city claimant interview or postpone; no force is necessary to advance.'},
      placement:{id:'ninepin-clinometer-n9-14',default:'If 25a has never been thoroughly searched in actual play, place a dented canvas sleeve beside the already-keyed picks and shovels at its tunnel mouth. The object is a custom addition to the equipment, not one of the book’s treasures. It was left by a prior survey crew whose fate remains unknown; do not assert a specific death.',custodian:'If Gilded Compass have actually reached 25a first in the prepared timeline, they can have recovered it and logged its serial. Establish their path 1→2a→2b→25a and their turnback before moving them. They can meet the party at the Portal, an agreed safe rendezvous, or the same physical corridor.',clearedFallback:'If 25a was searched, emptied or claimed, honor that record. Use an existing recorded item holder if one exists. Otherwise give Orren an ordinary city salvage receipt showing N9-14 offered by a returning unnamed crew; allow a city inquiry and defer the dungeon visit until that lead is resolved. Do not claim the party missed a new object in a completed search.',competingClaim:'Orren retains a workshop purchase record; Kestrel, if current finder, claims salvage labor and credit under her crew’s independent survey contract. Neither document decides Waterdeep law automatically. Agree a voluntary settlement or leave custody unchanged pending review.',sample:'Ordinary loose stone dust in the sleeve can be divided by permission into labeled control/sample dishes. It is neither an edible test nor proof of a magical network.'},
      route:{rooms:['um1-1','um1-2','um1-25'],description:'Entrywell 1 → actual 2a/2b approach → southern stairs and corridor → 25a tool pile and excavation mouth. Area 25a→25b uses the published 5-foot-wide, 5-foot-high rough tunnel. Stop at 25a unless the party chooses and can support the extra survey.',alternatives:['If the current holder already returned to Waterdeep, run a city settlement and instrument inspection; the dungeon can be a separate verification outing.','If 2b is blocked, negotiate or observe from the known approach, seek an actual guide or return. The room-1 north door is one-way, and area 21 is not a free bypass.','If the instrument was relocated by a recorded carrier, follow their witnessed route or ask them. Unknown location remains unknown; do not place a duplicate at 25a.','Only if requested: follow 25a’s crawl-through to 25b, measuring clearance and exit order. Beyond, the western passage leads toward 24/23 and the southern branch leads toward 26a/26c; a gelatinous cube begins at 26c. Farther routes require fresh preparation.','Floor 2 is a later extension only after an earned route to 39a, resolving/avoiding its actual defenders and explicitly preparing the descent. The preferred floor-2 research overlay is not moved into 25a.'],retreat:'Return 25a → north along the same corridor → 2b → 2a → 1. A heavily carried instrument must leave hands/light available; review movement through the 5-foot excavation tunnel only if entered. If scouts were alerted, reassess their recorded route rather than spawning replacements.'},
      beats:[
        {id:'arc-instrument-offer',title:'Orren’s description',scene:'wd-research',read:['Orren sets a drawing of a brass instrument on the bench. One foot in the drawing has a small, uneven notch. “That mark is mine. I can make another tool. What I cannot replace is an honest account of what happened to this one.”'],run:['Show the custom description and approved placement clue, not a room number the party does not know. Orren can describe the excavation approach only from a dated report: label it a report until verified.','Agree the 80/20 gp offer, damage terms, salvage budget and who can negotiate. If the serial or claimant is uncertain, the first objective is identification.','Orren seeks recovery and fair settlement; he will not pay for an assault disguised as salvage. Do not turn this into a city-law judgment without an actual relevant source and play.','Let the crew choose to ask rivals first, descend along the measured route, or decline. This can be a short city negotiation plus optional expedition, not a forced dungeon crawl.'],private:['This is a proposed object and contract. No previous courier, victim or owner has been added to confirmed history. Show players only the relevant public description.'],ask:['What would count as enough evidence if you cannot bring it back?','May another finder be paid from the recovery fee, and by whom?'],sources:[ref(22,'Area 25 tool pile and excavated connection support the custom placement.'),ref(15,'Actual access from the entry and southern corridor.'),...sources]},
        {id:'arc-instrument-rival',title:'An offer from the Gilded Compass',scene:'wd-portal',read:['Kestrel places her closed notebook on the table without sliding it toward you. “We can compare what each of us is willing to share. Routes have names attached to them. So should the people who do the measuring.”'],run:['Use only facts true for the crew at this moment. If they have no instrument, offer a reciprocal exchange: one verified corridor description for one of theirs, with visible redactions and agreed credit. If they hold N9-14, show its serial through the sleeve without handing it over.','Proposed opening claim if they recovered it: 25 gp for salvage time, or reciprocal publication credit plus an agreed piece of useful route information. They can negotiate; Orren’s consent is needed before spending his money. Players can instead request a condition report and leave the tool with its holder.','Pell wants reliable route notes; Nym wants enough time to inspect the glass vial without being rushed; Kestrel wants public credit. Ask what they offer in return. A conflict among priorities is a discussion, not inevitable theft.','If talks fail, record refusal and the exact current custodian. The Compass follows its own bounded survey plan; it does not race ahead, steal, rescue or reveal player secrets because the plot needs it.','If the rival crew will be underground, place their actual path and turnback plan before staging. A shared rendezvous is proposed, not instant movement.'],private:['The rival crew’s detailed goals and relationship cards are in the arc cast. Their future suspicious-delivery contract is not revealed in this first meeting.'],ask:['Would you trade a verified route, money, credit, or nothing?','Which pages of your notes stay private?'],sources:[ref(6,'Portal social setting; the Gilded Compass and contract are custom.'),{book:'custom',label:'Echo-Below-Campaign-Outline.md',note:'Expedition 2: rivals trade credit and follow their own contract.'}]},
        {id:'arc-instrument-reentry',title:'Use the route you earned',scene:'um1-table',read:['The first mark is still where you left it, if the passage has remained undisturbed. Ahead, the junction opens toward the branch your last survey left unfinished.'],run:['Read the conditional sentence only if the saved mark remains present; otherwise describe the actual change and its evidence. Use Preview return to saved expedition to carry current characters into the same floor.','Reconcile Undertaker terms, surviving scouts, known doors and the previous turnback. Their response depends on approved events, not contract number.','Keep 2b’s mind-detecting scouts only if not already removed or relocated. Do not reset them or an emptied pillar cache. If the route changed, show the concrete observation and propose the cause privately; a theory is not a confirmed faction action.','Let Pebble lead with the actual map, Trista choose light/scouting, and any player call a turnback. Reusing a correct map should visibly save decisions and uncertainty.'],private:['Arrival does not advance time, spend supplies or decide a rest on its own. Use the existing expedition review.'],ask:['Which mark or landmark confirms your position?','Does your earlier turnback rule need changing today?'],creatures:creatures.scouts,sources:[ref(15,'Saved physical route.'),ref(16,'Area 2b scouts only if still present.')]},
        {id:'arc-instrument-excavation',title:'The tool pile at 25a',scene:'um1-table',read:['Three picks and two shovels lie across rough stone at the mouth of a low tunnel. Rubble crowds the floor. The passage beyond is barely high enough to crawl through without bowing your head.'],run:['The keyed dead goblin is present only if not already moved; its caved-in skull records cruelty, not an automatic new combat. Keep its fate separate from the missing survey crew.','If using the unexplored-room placement, add: “A dented canvas sleeve rests beside the tools.” Searching the visible sleeve reveals the mundane instrument; no mandatory roll hides the contract behind a search failure. If a recorded holder removed it, show only whatever evidence they actually left.','Compare N9-14, the offset notch and Orren’s drawing. A careful visual check establishes visible matches and damage; it cannot prove the tool’s complete history.','Optional custom uncertainty: if attempting a hurried calibration under threat, call for DC 12 Intelligence with an appropriate tool proficiency after explaining the stakes. Success yields a usable rough bearing; failure means unreliable readings and time needed at a bench, not destruction or a false magical fact.','The tunnel to 25b is 5 feet wide and high. Use actual character size and squeezing rules where applicable; do not assume Pebble has a size or climbing power not on his sheet. No invented cave-in roll for ordinary transit. Bracing is an optional researched improvement, not an automatic hazard repair.'],private:['The custom instrument remains a mundane prop and inventory candidate until the DM approves its recovery/custody. Area 25b’s cobra-headed statue remains the book’s find.'],ask:['Who carries the instrument, and whose claim are you preserving?','Do you stop here or measure the far end of the tunnel?'],sources:[ref(22,'Areas 25a and 25b; exact tools, dead goblin and tunnel dimensions.'),ref(15,'Southern corridor and excavation connectivity.')]},
        {id:'arc-instrument-negotiation',title:'Two claims, one instrument',scene:'um1-table',read:['The case lies between the people who want it. For a moment, the dungeon is quiet enough to hear the little plumb bob tap against its brass frame.'],run:['Use this beat only if rival claimants are physically present; otherwise stage the same conversation in Waterdeep. Establish who currently holds the instrument and whether all parties can leave safely.','Offer three concrete settlements: buy the agreed salvage share; preserve Orren’s ownership while naming the finders in the public report and exchanging one agreed map segment; or have the holder keep it while a neutral bench inspection produces a paid fate report. No option requires Trista’s token or Aldric’s signet.','The party can offer another fair plan, refuse or protect an injured rival without surrendering every claim. A favor is recorded with its exact scope, not a lifetime debt.','If an attack interrupts, only actual nearby warned inhabitants can arrive along mapped passages. Stop negotiation, show exits and resolve the threat with proper stat blocks; do not summon an arbitrary mob to force cooperation.','If the party chooses robbery or violence, record witnesses, injury, ownership claims and likely complaints for later DM review. Do not make everyone instantly hostile or erase independent NPC priorities.'],private:['Insight can assess demeanor and inconsistencies, not establish legal ownership. Any persuasion roll changes willingness within stated limits; it does not alter past facts.'],ask:['What does each side need to be able to say honestly when they return?','Who is allowed to copy the serial, map or maker’s mark?'],sources:[ref(13,'Nearby faction motives for any response actually triggered.'),ref(15,'Physical approaches; no reinforcements through walls.'),{book:'custom',label:'Echo Below: recovery contract',note:'Competing salvage terms are original preparation, not a published room reward.'}]},
        {id:'arc-instrument-detour',title:'At the edge of the prepared route',scene:'um1-table',read:['Beyond the low tunnel, another hall continues past the place you came to find. The instrument does not require you to follow it.'],run:['If they stay within scope, return now with the actual result. If they enter 25b, its half-buried statue head is cobra-shaped when the debris is cleared; no Echo label is attached to it.','If they explore the southern clean-tunnel branch as far as 26c, open that exact room card: a gelatinous cube begins around its corner unless moved or removed by prior play. Passive Perception 15 or higher avoids the keyed surprise. Clean passages and floating candles do not establish safety. The 26b closet is empty. Use the full MM p.242 stat block and Engulf/Ooze Cube rules.','If they circle west/north toward 24, stage 24’s real approach. Crossing between the ruined gate pillars invokes the keyed d12 effect: 1–2 DC 12 Constitution, 4d10 force (half success); 3–7 no effect; 8–11 invisibility for 1 hour, ending on attack/spell; 12 carried nonmagical weapons become +1 for 24 hours. The gate does not travel anywhere. Record expiry.','Do not lead the party through the arch merely to trigger a set piece. Show actual space and let them avoid it when physically possible. Room 23 contains the saved Guild post, not an innocuous shortcut.','The floor-2 research scrap stays in its earned floor-2 context. If no route there exists, Orren can later discuss a legitimately sourced copy with provenance, or simply ask for a future comparison. A complete radial diagram and Looking Glass explanation are not added here.'],private:['This is an extension warning with source links, not a requirement to visit 24/26 or clear Worg’s Eye. Stop and prepare a longer expedition if the group chooses one.'],ask:['Does learning the next route justify the time and remaining resources?'],creatures:[{name:'Gelatinous Cube',count:1,book:'mm',page:242,note:'Area 26c only, if still present; not on the direct western passage to 24.'}],sources:[ref(21,'Area 24 residual wild magic, not transit.'),ref(22,'Excavation and clean tunnels.'),ref(15,'Routes beyond 25b.')]},
        {id:'arc-instrument-delivery',title:'A bench test, not a revelation',scene:'wd-research',read:['Orren clears a place on the bench before anyone opens the case. “Tell me who handled it, what changed, and what you want left untouched. Then we can find out whether it still measures straight.”'],run:['Compare the object/report against the agreed contract. Review compensation, salvage cost, debt and custody separately before changing inventory. If no recovery occurred, read the corroborated fate report and honor only its agreed fee.','Offer Pebble a rubbing of an ordinary maker’s mark that resembles a technique on his hammer only if he agrees to comparison. It suggests a useful workshop inquiry; it does not name a missing colleague, establish kinship or prove anyone’s fate.','Offer Donavan labeled ordinary dust and a repeatable baseline measurement, by consent. A sample’s location and handler matter; a surprising result remains an observation with possible ordinary causes.','If an authenticated research fragment has actually been obtained from an earned location, discuss its limited wording and provenance. Otherwise use a blank comparison worksheet, not an invented find.','Move to the separate courtyard return beat and optional private correspondence. No reply from Dianna or request from Mara is delivered merely because this card exists.'],private:['Orren neither identifies Aldric’s resurrection nor connects every artisan to Halaster. Distinguish original overlay hints from the published room record.'],ask:['What do you want tested, copied, kept private or left alone?','Do you want the follow-up to be another expedition, a maker’s letter or a quiet day?'],sources:[ref(22,'Original location anchor only; instrument and maker comparison are custom.'),{book:'custom',label:'Echo-Below-Campaign-Outline.md',note:'Expedition 2 earned maker clue, comparison and conditional homecoming.'}]}
      ],
      responses:[
        {trigger:'Instrument recovered by a named crew',evidence:'Dated recovery, serial verification and actual custodian.',proposal:'Move that one object with its carrier; let later searches find it absent and any real signs of removal.',preserves:'No duplicate tool and no retroactive theft from the party.'},
        {trigger:'A salvage agreement is honored',evidence:'Accepted terms, credited note or actual payment.',proposal:'The Compass can share the specific promised map section or agree to one later joint inspection.',preserves:'They retain their own contract, private pages and right to decline unsafe work.'},
        {trigger:'A claim remains unresolved',evidence:'Recorded holder and each side’s stated claim.',proposal:'Offer a city inspection, paid report or later negotiation instead of moving the goal farther into the dungeon.',preserves:'No presumed theft, fabricated missing person or automatic quest failure.'},
        {trigger:'Departure leaves an observed route exposed',evidence:'Specific open door, warning witness or abandoned light, plus a surviving nearby actor.',proposal:'Stage a bounded patrol or inspection for DM approval, with the actual path and elapsed time.',preserves:'Cleared rooms and disarmed hazards stay cleared/disarmed unless a recorded actor changes them.'}
      ],
      spotlights:{'pc-pebble':'Primary: decide how to compare the maker’s mark and whether to contact his hammer-makers. Lead the low-tunnel clearance and return marks using his actual size and abilities.','pc-donavan':'Primary: identify the instrument from ordinary evidence, keep sample provenance, and ask a testable research question. Dianna’s reply can respond to an actual letter.','pc-ringgo':'Negotiate salvage credit or a paid report that satisfies competing practical needs. No past contact must betray him.','pc-trista':'Choose custody protections, escort an injured person if any, or bargain over exactly what gets copied; her private discovery remains hers to discuss.','pc-aldric':'Witness a voluntary agreement and insist on safe stop rules during inspection. Atonement can be a concrete protective choice without a forced recollection.'},
      rewards:['Agreed 80 gp recovery or 20 gp corroborated report, crediting the report against later recovery if that was agreed. No automatic payment or double award.','Voluntary workshop service can replace some payment at an explicitly agreed value; it is not unlimited free crafting.','A permitted maker-mark copy, ordinary labeled sample or credited map exchange actually obtained through play.','A resolved claim or documented reason it remains open; both can support the next choice.'],returns:['Orren confirms only what his inspection established; unresolved ownership and repairs remain visible.','Dianna’s private reply requires a real sent letter and plausible interval. Mara’s object-specific interest requires a credible disclosure or witness; otherwise her invitation is general.','Preserve the current dungeon and choose the next passage from the actual measured routes. No floor-2 travel or major mystery revelation has been awarded.'],limits:sharedLimits,sources
    },
    {
      id:'passage',title:'Terms of Passage',questId:'passage',summary:'Make a small stretch more dependable by discovering who can honor which terms. Record limits, warnings and refusals as carefully as promises.',
      prerequisites:['At least one actual surveyed route or current guide makes the proposed corridor intelligible; do not publish unknown map rooms.','Check actual Undertaker and Guild survivors, leadership, relocations, promises and breaches. Neither faction respawns for this job.','Pick a useful bounded destination: recommended excavation approach at 25a. Add a northern 6a rendezvous only if actually observed, wanted by the party and separately permitted by its current keepers. A meeting point is not a safe refuge or a right to rest. This is not an agreement to reach Skullport.','Agree who benefits from the route, what information can be shared, the proposed trial window and the turnback if either side refuses.'],
      contract:{scope:'Ilvara proposes a practical route sheet for well 1→2a→2b→southern approach25a. This southern lane does not cross Undertaker territory. If the party wants a separate rendezvous for outgoing and returning survey teams at the already-observed 6a threshold, negotiate it as an optional northern staging clause: a brief supervised meeting, never an assumed refuge. Name who controls each stretch, signals, exclusions, review date and emergency turnback. A contract for one faction’s territory cannot bind another.',payment:'Suggested custom offer: 60 gp for the group after a witnessed trial of honestly bounded arrangements and stated unresolved limits; or 30 gp for a corroborated negotiation/refusal report showing why a dependable route is not yet available. The latter is credited toward the 60 if later completed. Agree before leaving.',delivery:'Provide named speakers, exact route segment, start/end or visit limit, consideration, permitted travelers, weapons/light expectations, breach terms and a demonstrated retreat. Any untested assurance stays marked claimed. Warn future users about known unreliable promises.',partial:'Refusal or lack of an authorized survivor is a useful outcome. Publish the last safe stopping point and an evidence-based restriction; propose another known route or postpone. Do not require killing everyone or completing a deeper floor to collect an honest report fee.'},
      route:{rooms:['um1-1','um1-2','um1-6','um1-23','um1-24','um1-25'],description:'Primary travel lane is the established 1→2a→2b→25a; it does not cross area 6 or require an Undertaker toll. If the party chooses a supervised rendezvous at the previously observed 6a threshold, negotiate that northern side trip separately along the mapped approach. It is a meeting point, not a presumed refuge or resting place. Contact at Worg’s Eye is an optional, separately prepared extension: 25a → low tunnel 25b → its west door → unkeyed western passage → 24b south door → 24a north exit → the southern area-23 corridor → 23a/23b, resolving the actual gate approach and guards. Area 23c opens off that corridor; it is not the route into 23b. The 26b closet opens from 26a and is not on this western passage. The cube starts in 26c on the separate southern branch, not automatically on this route. Do not route negotiators through the lethal mirrors in 21 as a shortcut.',alternatives:['Parley with a currently present scout at a visible threshold, while retaining the well route; scouts cannot promise universal protection and will not all become honest through a check.','Send an in-world written proposal through an actual willing messenger, with return time and no compelled visit to 23; receipt and response remain unconfirmed until observed.','If bugbears/intellect devourers have been removed by prior play and surviving goblins can speak for their own group, negotiate an actually limited goblin passage agreement. No past kills are invented to enable this.','If the Undertakers have been defeated, their former rooms stay cleared until a concrete new claimant arrives. Do not demand a toll from a dead leader. The route can instead be surveyed as presently unoccupied, with limits on continuing safety.','If northern staging creates incompatible obligations, drop that optional benefit and certify only the observed southern lane with its actual Guild risks. The Undertakers do not acquire a toll over 1→2→25a because negotiations happened.','If either relevant faction refuses, deliver a restriction and turnback map; explore a separately prepared physical route on another day. The contract may be completed as a report without establishing safe transit.'],retreat:'For the primary lane, return 25a→2b→2a→1. For a deliberate Worg’s Eye visit, preserve the actual area-23 southern corridor → 24a → 24b south door → unkeyed western passage → 25b west door → 25a detour and its current hazards; do not count a blocked or untraversed mirror route as an exit. Carry the agreement and return signal, not a magical safety guarantee.'},
      beats:[
        {id:'arc-passage-brief',title:'Who can actually promise passage?',scene:'wd-portal',read:['Ilvara lays two sheets over the map. “One for the route. One for the promises. I would like the second to be as accurate as the first.”'],run:['Choose the bounded southern lane and trial users: the party alone first, with later surveyors only if named in the agreement. The lane 1→2a→2b→25a does not pass through Undertaker rooms. Ask whether the party actually wants an additional supervised rendezvous at its already-observed 6a threshold so a returning survey team and an outgoing one can compare route changes without waiting in the pillar junction. If not useful or not yet observed, omit it.','Review current participants. Undertakers want income, privacy and advantage over each other; Guild bugbears want to restrict deeper access and capture an Undertaker leader for replacement. Those are published interests, not information the PCs automatically know.','Proposed custom conflict, if the northern rendezvous is wanted and Harria’s golem still exists: the relevant Undertaker keepers require traffic notice and a promise not to attack or help remove their golem; the Guild offers passage only if the party removes it, and intends to break that bargain. The promises are incompatible. Explain the actual demands as each side voices them; the PCs can seek narrower terms, refuse the Guild demand, or drop northern staging entirely. Neither choice cures Guild hostility.','Ask what the players will not promise. Protecting civilians or refusing an assassination can be a valid limit, even if it prevents an agreement.','Separate a private clause from information later map users need for safety. A promise to hide a threat cannot silently become a safe-route advertisement.'],private:['The published bugbears offer passage for disposing of Harria’s golem and do not keep that bargain (p.13). Do not make their scripted dishonesty vanish after Persuasion. A verified, limited arrangement requires actual enforceable conditions or surviving goblins after their overlords are gone through play.'],ask:['Who needs this passage, and to what exact point?','What promise would you refuse even if it cost the contract?'],sources:[ref(13,'Conflicting faction goals and the bugbears’ unreliable golem bargain.'),ref(15,'Limited route and physical return.')]},
        {id:'arc-passage-undertakers',title:'A northern agreement, with limits',scene:'um1-table',read:['The speaker studies the narrow line you have drawn on the map. “You want to pass. I want to know when strangers are walking behind me. There may be a version of this conversation we both survive.”'],run:['Choose the actual living Undertaker who has authority here. With Uktarl, emphasize fees and public status; with Harria, control of the approach, her golem and refusal to be humiliated. If neither remains, use the recorded replacement or remove the negotiation entirely.','Suggested custom staging terms: one named group and one short meeting at the 6a threshold during an agreed watch; advance notice with a visible signal; no private-room entry or interference with defenses; and 10 gp for that single group visit if accepted. The default extortion demand remains 10 gp per person. This applies only to voluntarily entering their northern territory; the southern lane carries no automatic Undertaker toll.','If Harria and her golem survive, propose her condition for cooperating with the northern rendezvous: traffic notice and no attack on, removal of, or assistance against the golem. These are custom negotiated terms consistent with her published reliance on it. Uktarl cannot promise Harria’s cooperation; obtain the relevant living keeper’s assent. If the golem or leaders are gone, rewrite this condition from actual play instead of restoring them.','Ask the leader to name who will honor it. Uktarl does not bind Harria merely by saying so. A separate confirmation or witnessed local escort can support only the area actually covered. The party can refuse northern staging and use only its known southern route without owing an invented northern toll.','Expose the costume with DC 14 Insight if attempted; learning the ruse does not prove promises truthful. If conflict erupts, preserve area 6 composition and retreats, and area 8’s captain/golem and disguises.','If considering area 8 contact, telegraph the dead wyvern and bone throne; sitting or lifting its seat triggers two +8 snake attacks, each 1d4+1 piercing and DC 13 Constitution for 7d6 poison, half on success. The compartment is empty. Do not seat a negotiating PC on it without describing the object first.'],private:['Harria cannot control a berserk flesh golem. A bargain involving the golem must acknowledge the actual risk; it is not a free allied bodyguard. No critical information depends on walking into the throne trap.'],ask:['Which of your people are bound by this, and what happens if one is absent?','What does the payment cover that the map itself cannot promise?'],creatures:[...creatures.undertakers,{name:'Bandit Captain',count:1,book:'mm',page:344,note:'Harria, area 8 only if present; Performance+4.'},{name:'Flesh Golem',count:1,book:'mm',page:169,note:'Area 8 only if still present; obeys Harria except when berserk.'},{name:'Bandit',count:5,book:'mm',page:343,note:'Area 8c survivors only.'},{name:'Doppelganger',count:1,book:'mm',page:82,note:'Area 8c survivor only.'}],sources:[ref(13,'Leaders, disguises and conflicting interests.'),ref(17,'6 and 7; local force and retreat.'),ref(18,'Harria, golem and bone-throne trap.')]},
        {id:'arc-passage-guild-contact',title:'The offer that cannot be taken on trust',scene:'um1-table',read:['The answer comes after a long look at your weapons. “The large stitched creature is a problem. Remove it, and perhaps your little journeys will stop being ours.”'],run:['Use this line only from a live Guild bugbear in an actual contact. If no contact occurred, send no automatic answer. Describe observable body language and terms rather than revealing intellect devourers through narration.','The book’s bugbear bargain is to remove the flesh golem for passage; they do not intend to honor it. A successful Insight assessment can reveal pressure/inconsistency through your normal contested adjudication, but never guarantees detecting a hidden monster or makes the lie binding.','The party can ask for a staged proof: one escorted retreat now before any service, names of posts expected to honor it, or independent confirmation. The bugbears may refuse, stall, provide a limited self-interested concession, or withdraw. That bounded action is observed; future safety remains claimed.','If the party already promised to protect or leave the golem undisturbed for northern staging, the Guild demand directly conflicts with that clause. Show both promises together. The party can try removing the golem demand from the offer, reject the Guild terms, or release and abandon northern staging by agreement. Dropping that benefit does not make the Guild honest or grant passage.','No contract requires agreeing to murder or sabotage Harria. Record refused terms and return. A report that this route cannot safely be certified meets the partial scope.','If the overlords were actually defeated earlier, the published goblins readily honor passage from self-preservation when all relevant bugbears and intellect devourers are dead. Do not treat killing one visible host as clearing its devourer, or a local goblin as controlling every floor-1 post. Agree the segment that those survivors actually control.'],private:['Guild kidnapping/replacement ambitions are DM motives until evidence is earned. Do not tell Aldric that the Guild explains his own return, or have Halaster endorse a killing bargain.'],ask:['What evidence would make you believe this speaker can honor the terms?','Will you accept a limit, demand a safer first step, or leave?'],creatures:creatures.scouts,sources:[ref(13,'Exact guild goal, kidnapping scheme, golem bargain and goblin exception.'),ref(16,'Possible scout contact in 2b.'),ref(21,'Worg’s Eye actual roster.')]},
        {id:'arc-passage-worg-approach',title:'Optional visit to Worg’s Eye',scene:'um1-table',read:['Old masonry gives way to the rough excavation you have already measured. Farther on, the route bends toward voices. There is still time to announce yourselves from a distance.'],run:['This is optional and only after the route was actually traversed. Follow 25a → 25b west door → unkeyed western passage → 24b south door → 24a north exit → the southern area-23 corridor → 23a/23b. Area 23c is a side room; 26b is reached from 26a, not passed on this route. Check the marked map and every saved obstruction; no corridor is skipped because it is a negotiation scene.','The cube starts in 26c on a different, southern branch; do not move it onto this route without a recorded patrol path and elapsed time. Area 24’s broken gate retains its crossing-triggered wild magic. Open their keyed cards before proceeding. Do not force crossing the arch where the map permits another line.','Area 23 native roster: two bugbears with intellect devourers, six goblins in 23a and nine sleeping goblins in 23c; add only surviving area 2b scouts that actually arrived. Detect Sentience matters. State the parley signal from cover/outside the post and let inhabitants answer.','The guards’ statue project can be recognized with DC 15 Intelligence (Investigation) as three warriors on a mound; repair or trade can be a local incentive but does not erase their guild orders. Their noisy skeleton game in 23a is a published scene, not a new captive to rescue.','If fighting starts, use local positions and actual warning paths. Goblins whose leaders die flee toward 28 via 24/25; track them once. If they surrender or flee, mark those choices rather than removing every occupant as dead.','Retreat remains a valid conclusion. Check whether a recorded hazard movement, blocked passage or alerted force makes the outward path unsafe before describing it as open.'],private:['Keep all offscreen rooms concealed. A missing patrol or a closed door creates a question; propose the responsible actor only when evidence supports it.'],ask:['Do you call from here or take another step?','Who watches the return bend while the others speak?'],creatures:creatures.guild,sources:[ref(21,'Worg’s Eye roster, statue, goblin retreat and broken gate.'),ref(22,'Excavation connection. The separate 26a branch leads to the empty 26b closet and cube at 26c.'),ref(15,'Exact approach through 24 and 25.')]},
        {id:'arc-passage-trial',title:'Test only the promise you made',scene:'um1-table',read:['You reach the point named in the agreement. The map tells you where you are. The next few moments will tell you whether the promise reaches this far.'],run:['If no agreement was achieved, replace this with a final observation from the known safe stopping point; the refusal report remains useful.','For a trial, state the exact covered segment, travelers, signal and time. Traverse the same actual route with the current party first. A group’s noninterference at one threshold verifies that act, not every future visit.','If challenged, show why: a named guard not informed, changed leader, missed signal, expired window or intentional deception supported by the actor’s motives. Allow the party to present terms, renegotiate or withdraw. Do not choose an unexplained betrayal merely to create a fight.','Record observed compliance separately from the promise. Mark the farthest verified point and any danger outside the agreement. Guild hostility and autonomous predators remain real even if the Undertaker clause holds.','A cleared corridor can earn provisional status without a living toll collector. Preserve its success; propose future claimants only if a nearby survivor, motive, time and actual route support them.'],private:['This trial does not change the route status automatically or complete an unrelated quest. Review the native route entry, agreement, witnesses and relevant quest step together.'],ask:['What can the next group safely rely on, and what must they check again?','Where does your certification end?'],sources:[ref(13,'Faction authority and limits.'),ref(15,'Bounded trial path.'),ref(26,'Aftermath follows actual surviving forces.')]},
        {id:'arc-passage-note',title:'Optional: a courteous observer',scene:'um1-table',read:['A small folded note rests where the light catches it. The paper is dry. The handwriting is unhurried.'],run:['Use at most once, after a genuine third-expedition accomplishment, and only where an observer could plausibly have watched a public dungeon action. Skip it if recognition has no credible basis yet.','Write one accurate, nonprivate observation from this expedition: “You waited for the last member of your company at the turn. Sensible.” Change that sentence to match an actual action; never claim a memory or private conversation.','Add one bounded warning chosen from an unresolved keyed hazard the party has not already neutralized: “The sword beside the severed hand is reluctant to be put down” (area 4); “The throne of bone rewards neither sitting nor curiosity” (8a); or “A clean corridor can have an appetite” (26c). Sign only “Your host.”','Let the party test the warning, ignore it, preserve the note or suspect a prank. Handwriting/signature alone does not prove authorship. Do not create a map change, required curse or new threat to make the note true.','No family name, experiment title, resurrection claim, Nine diagram or demand for service appears. Do not use Aldric’s ring as a beacon.'],private:['Custom first clear attention cue; intended author Halaster, in-character authorship is still a claim until corroborated. His useful warning is not consent to interfere and does not settle his motives. Keep preparation off all player displays until this scene is actually used.'],ask:['Who keeps the note, and who may see a copy?','Do you want to test the warning or leave it for another day?'],sources:[ref(16,'Area 4 sword warning option.'),ref(18,'Area 8a throne warning option.'),ref(22,'Area 26c cube warning option.'),{book:'custom',label:'Echo-Below-Campaign-Outline.md',note:'Expedition 3: a courteous, bounded note; no major revelation.'}]},
        {id:'arc-passage-report',title:'Put the limits on the map',scene:'wd-portal',read:['Ilvara reads the route once and the promises twice. Then she leaves a clear blank below the final line. “What would make this stop being true?”'],run:['Deliver the actual result: verified limited trial, untested promise, refusal or obstruction. Resolve only the agreed 60/30 gp payment and any credited earlier report fee.','Create or correct the route record with exact end point, limits, date and evidence; attach the agreement outcome rather than copying a contradictory second history. Include only public-safe terms in a shared map.','Propose actor responses for DM review: a warned post watches that lane, a keeper honors a paid window, a deceiver has been exposed, or a survivor seeks another patron. Name the evidence and do not reverse successes without a concrete cause.','Offer the optional personal messages and ordinary courtyard return. Record current objectives without forcing a deeper descent. A dependable small route is enough for this act’s first arc.'],private:['No completed contract automatically makes the whole floor safe, restores dead leaders, grants faction membership or opens Skullport. Leave major Halaster revelations for later earned sources.'],ask:['Who should receive the map and its warnings?','What is the smallest useful next expedition?'],sources:[ref(26,'Level 1 aftermath; concrete developments only.'),{book:'custom',label:'Echo-Below-Campaign-Outline.md',note:'Third return, ordinary home life and later small observed anomaly.'}]}
      ],
      responses:[
        {trigger:'Named Undertakers honor a limited agreement',evidence:'Actual terms, paid consideration, witnessed compliance and remaining leadership.',proposal:'Preserve covered access through its agreed window. If succession or a witnessed breach occurs, propose a specific review before changing it.',preserves:'An earned arrangement remains useful; unrelated predators and guild posts were never covered.'},
        {trigger:'Guild bugbears offer the golem bargain',evidence:'Recorded offer from a currently present bugbear and published hostile intentions.',proposal:'Keep it classified as an unverified claim; let refusal, attempted verification or the specific planned deception drive a reviewed response.',preserves:'No fake guaranteed passage and no automatic combat obligation.'},
        {trigger:'All relevant bugbear/devourer leaders were actually removed',evidence:'Confirmed creature outcomes, not host HP alone, plus named surviving goblins.',proposal:'Allow surviving goblins to honor a limited passage out of self-preservation; determine their actual territory and warn that other posts may differ.',preserves:'No invented prior kills, new leader resurrection or map-wide treaty.'},
        {trigger:'A cleared post leaves an opening',evidence:'Saved cleared rooms, a real nearby would-be claimant, available route and elapsed time.',proposal:'First show signs or a proposal for that actor’s scouting; review any later occupation before applying it.',preserves:'Clearing the post remains an established success; no automatic replenishment or lost treasure.'},
        {trigger:'A reliable trial or honest refusal is delivered',evidence:'Witnessed trip/refusal and agreed delivery terms.',proposal:'Pay the reviewed fee, attach a specific route status and publish only approved warnings.',preserves:'Unrelated quests, private character discoveries and hidden routes remain unchanged.'}
      ],
      spotlights:{'pc-ringgo':'Primary: negotiate a limited legitimate agreement and receive the optional private old-contact request on return. Helping someone leave old work is a choice, not compulsory crime.','pc-aldric':'Primary: distinguish coercion from consent, set enforceable exit terms, and seek the records specialist’s name privately. No family or resurrection identity is revealed.','pc-pebble':'Verify the retreat marks and practical carrying/clearance needs; his map helps real travelers without requiring reckless tunnel work.','pc-trista':'Choose what a shared agreement may expose; protective scouting or quiet observation matters. No faction identifies her token by intuition.','pc-donavan':'Write the conditions under which a claim was tested, record contradictory testimony and decide what can responsibly be published.'},
      rewards:['Agreed60 gp after witnessed limited trial or30 gp corroborated refusal/report, with any later balance handled explicitly.','A real access window, current route warning or a deliberately chosen turnback; usefulness is bounded by actual authority.','Earned relationship changes for people whose promises were kept, with exact favors and independent interests retained.','Optional private introductions, a recovered note and later observed anomaly only if staged and played; none is a completed revelation.'],returns:['Run the normal courtyard evening first. Invite the two optional private personal leads without public disclosure.','Only afterward, if appropriate, stage the small patched-wall anomaly with two actual observers. Record duration, sketch and what each saw, not a theory about restoration. No resident is harmed.','Review the three expeditions’ actual evidence, unresolved agreements and current next choice. The party may rest, improve home, follow a personal lead or delay any deeper expedition.'],limits:sharedLimits,sources
    }
  ];
  globalThis.ECHO_UNDERMOUNTAIN_ARC_DATA = {version:1,status:'future-preparation',source:custom,packages};
})();
